            var p=chat.getPlayer();manualWaiting.set(true);var body=new net.minecraft.network.chat.SignedMessageBody.Packed(chat.getRawText(),java.time.Instant.now(),0,new net.minecraft.network.chat.LastSeenMessages.Packed(List.of()));var type=net.minecraft.network.chat.ChatType.bind(net.minecraft.network.chat.ChatType.CHAT,p).toNetwork(p.level().registryAccess());p.connection.send(new net.minecraft.network.protocol.game.ClientboundPlayerChatPacket(p.getUUID(),0,null,body,chat.getMessage(),net.minecraft.network.chat.FilterMask.PASS_THROUGH,type));
